CREATE TABLE "CommercialPriceLevel" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"multiplierBasisPoints" INTEGER NOT NULL DEFAULT 10000,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CommercialPriceLevel_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CommercialDiscountRule" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"percentageBasisPoints" INTEGER NOT NULL DEFAULT 0,"fixedAmount" BIGINT NOT NULL DEFAULT 0,"minimumPurchase" BIGINT NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CommercialDiscountRule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InstallmentPlan" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"installmentCount" INTEGER NOT NULL,"firstDueDays" INTEGER NOT NULL DEFAULT 0,"intervalDays" INTEGER NOT NULL DEFAULT 30,"markupBasisPoints" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InstallmentPlan_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CommissionRule" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"rateBasisPoints" INTEGER NOT NULL,"basis" TEXT NOT NULL DEFAULT 'NET_AFTER_DISCOUNT',"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CommissionRule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CurrencyRate" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"currency" TEXT NOT NULL,"rateToIrr" BIGINT NOT NULL,"effectiveAt" TIMESTAMP(3) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CurrencyRate_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommercialPriceLevel_workspaceId_code_key" ON "CommercialPriceLevel"("workspaceId","code");
