CREATE UNIQUE INDEX "InstallmentPlan_workspaceId_code_key" ON "InstallmentPlan"("workspaceId","code");
CREATE UNIQUE INDEX "CommissionRule_workspaceId_code_key" ON "CommissionRule"("workspaceId","code");
CREATE UNIQUE INDEX "CurrencyRate_workspaceId_currency_effectiveAt_key" ON "CurrencyRate"("workspaceId","currency","effectiveAt");
